def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev_bids = []
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 0:
                    strong_prev_bids.append(bid)

    if not alive:
        return float(min(budget, 10.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strong_highest_prev = max(strong_prev_bids) if strong_prev_bids else highest_prev

    capacity = int(supply // WATER_REQ)
    if capacity < 1:
        capacity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if day >= 8:
        urgency += 1

    if capacity >= 2:
        urgency -= 1

    if desperate_count >= 2:
        urgency += 1

    if urgency >= 5:
        target = max(66.0, strong_highest_prev + 3.0)
    elif urgency >= 3:
        target = max(52.0, strong_highest_prev + 1.5)
    elif urgency >= 1:
        if strong_highest_prev >= 120.0:
            target = 34.0
        else:
            target = max(38.0, strong_highest_prev * 0.55)
    else:
        if strong_highest_prev >= 110.0:
            target = 18.0
        else:
            target = 26.0

    if supply >= 24:
        target += 4.0
    elif supply <= 16:
        target += 6.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * 1.2
    elif day <= 9:
        reserve_floor = DAILY_SALARY * 0.5

    spend_cap = budget
    if budget > reserve_floor:
        spend_cap = budget - reserve_floor + min(20.0, DAILY_SALARY * 0.3)

    if urgency >= 4:
        spend_cap = budget

    bid = min(target, spend_cap, budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, min(69.0, strong_highest_prev + 4.0)))

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Estimate yesterday's max bid among alive opponents
    yesterday_max = 0
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            yesterday_max = max(yesterday_max, trace['bid'])

    # Base bid factor on supply scarcity and hp
    if supply < 20:
        # Scarce water - need to outbid
        if hp <= 2 or no_water_days >= 1:
            bid_factor = 1.2
        else:
            bid_factor = 1.0
    else:
        # Plentiful supply
        if hp <= 2:
            bid_factor = 0.9
        else:
            bid_factor = 0.5

    target_bid = DAILY_SALARY * bid_factor

    # Adjust to beat yesterday's high if possible
    if yesterday_max > 0 and target_bid <= yesterday_max + 1:
        target_bid = yesterday_max + 2.0

    # Ensure not to exceed budget
    bid = min(budget, target_bid)
    # Floor at 0
    bid = max(0, bid)
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    # If no opponents, take what we can afford but don't overpay
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids and hp pressure
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass
        try:
            prev_hp_after.append(float(prev.get('hp_after')))  # may be missing
        except Exception:
            pass

    # Determine likely competitive level from yesterday
    # Cindy appears to be the only sustained bidder; others died with lower bids.
    # Use quantiles-like heuristic without sorting too much.
    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_prev = min(prev_bids) if prev_bids else 0.0

    # Supply pressure: with higher supply, we can bid less and still secure water.
    # With lower supply, we need to outbid the low group.
    # Convert supply to a coarse tier.
    if supply <= (MIN_SUPPLY + 1.0):
        tier = 0  # scarce
    elif supply >= (MAX_SUPPLY - 1.0):
        tier = 2  # abundant
    else:
        tier = 1  # medium

    # Base bid target: slightly above typical low bidders if they were dying.
    # Use highest_prev as a signal to avoid getting into a bidding war.
    # If highest_prev is very high (Cindy), we don't try to match it; we aim to secure enough.
    if highest_prev >= DAILY_SALARY * 0.85:
        # Cindy-like behavior detected: keep bid around low+margin, scaled by tier.
        margin = 6.0 if tier == 2 else (10.0 if tier == 1 else 14.0)
        base = (lowest_prev + margin) if prev_bids else (DAILY_SALARY * 0.35)
        # If our hp is critical, escalate.
        if my_status['hp'] <= 2:
            base *= 1.6
        elif my_status['hp'] <= 4:
            base *= 1.25
    else:
        # No extreme bidder: bid to beat the mid band.
        # Aim around median-ish using midpoint of min/max.
        band = (lowest_prev + highest_prev) / 2.0 if prev_bids else (DAILY_SALARY * 0.5)
        base = band * (0.85 if tier == 2 else (0.95 if tier == 1 else 1.05))
        if my_status['hp'] <= 2:
            base *= 1.5

    # Ensure we never exceed budget; also avoid bidding too low to be irrelevant.
    # Budget may be float; keep bid float.
    budget = float(my_status['budget'])

    # Minimum bid floor depends on hp urgency.
    if my_status['hp'] <= 2:
        floor_bid = DAILY_SALARY * 0.7
    elif my_status['hp'] <= 4:
        floor_bid = DAILY_SALARY * 0.45
    else:
        floor_bid = DAILY_SALARY * 0.3

    bid = float(max(floor_bid, base))

    # Hard cap: never bid more than a fraction of budget to preserve future days.
    # If we are low hp, allow larger fraction.
    if my_status['hp'] <= 2:
        cap_frac = 0.95
    elif my_status['hp'] <= 4:
        cap_frac = 0.8
    else:
        cap_frac = 0.6

    cap = budget * cap_frac
    if cap <= 0.0:
        return 0.0

    bid = min(bid, cap, budget)

    # If supply is very low and we have many no_water_days, consider escalation.
    if tier == 0 and my_status.get('no_water_days', 0) >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.65))

    return float(max(0.0, bid))
